/*
 * Chat plugins for Castiello et al. (2026) Experiment 3, with replies generated by the chat
 * service (server/) through ChatClient (src/chat-client.js).
 *
 * jsPsychChatSetup  sends the BFI answers to the service, which assigns the two bots. Shows
 *                   "Setting up your chats…"; retries on its own, then offers Try again.
 * jsPsychLiveChat   one chat with one bot. The bot speaks first: the page asks for the opener
 *                   (hidden message 0), then bot 1, participant 2, bot 3, ... Every message from
 *                   either side is one turn; the chat ends after `total_messages`.
 *                   "Stop and leave the study" is always offered (ended_reason "withdrew"). If the
 *                   service's safety check stops the chat, a notice (never a bot message) says so
 *                   and the participant may continue or leave (ended_reason "safety_stop").
 *
 * The trial data hold counts and timings only. The text of the chat is kept by the service
 * (and exported to the private transcripts file), never in the jsPsych data.
 */
var jsPsychChatSetup = (function (jspsych) {
  "use strict";

  const info = {
    name: "chat-setup",
    version: "1.0.0",
    parameters: {
      client: { type: jspsych.ParameterType.OBJECT, default: null },
      get_answers: { type: jspsych.ParameterType.FUNCTION, default: () => ({}) },
      force: { type: jspsych.ParameterType.OBJECT, default: null },
      auto_retries: { type: jspsych.ParameterType.INT, default: 2 },
    },
    data: {
      setup_ok: { type: jspsych.ParameterType.BOOL },
      setup_attempts: { type: jspsych.ParameterType.INT },
      setup_error: { type: jspsych.ParameterType.STRING },
    },
  };

  class ChatSetupPlugin {
    constructor(jsPsych) {
      this.jsPsych = jsPsych;
    }

    trial(display_element, trial) {
      return new Promise((resolve) => {
        let attempts = 0;
        display_element.innerHTML = "";
        const box = document.createElement("div");
        box.className = "instructions chat-setup";
        const status = document.createElement("p");
        status.className = "chat-setup-status";
        box.appendChild(status);
        display_element.appendChild(box);

        const buttons = document.createElement("div");
        buttons.className = "chat-end";
        const button = (label, cls, onclick) => {
          const b = document.createElement("button");
          b.type = "button";
          b.className = "jspsych-btn " + cls;
          b.textContent = label;
          b.onclick = onclick;
          buttons.appendChild(b);
        };

        const done = (ok, error) => {
          display_element.innerHTML = "";
          resolve({ setup_ok: ok, setup_attempts: attempts, setup_error: error || null });
        };

        const attempt = async () => {
          buttons.innerHTML = "";
          buttons.remove();
          status.textContent = "Setting up your chats…";
          for (;;) {
            attempts += 1;
            try {
              await trial.client.startSession(trial.get_answers(), trial.force);
              return done(true);
            } catch (e) {
              const retryable = e && e.retryable;
              if (retryable && attempts % (trial.auto_retries + 1) !== 0) {
                await new Promise((r) => setTimeout(r, 1500 * attempts));
                continue;
              }
              status.textContent = retryable
                ? "We could not set up your chats. Please check your internet connection and try again."
                : "Something went wrong while setting up your chats, so the study cannot continue.";
              if (retryable) button("Try again", "chat-retry", attempt);
              button("Leave the study", "chat-leave", () => done(false, (e && e.code) || "error"));
              box.appendChild(buttons);
              return;
            }
          }
        };
        attempt();
      });
    }
  }
  ChatSetupPlugin.info = info;
  return ChatSetupPlugin;
})(jsPsychModule);

var jsPsychLiveChat = (function (jspsych) {
  "use strict";

  const info = {
    name: "live-chat",
    version: "1.0.0",
    parameters: {
      chat_index: { type: jspsych.ParameterType.INT, default: 1 },
      bot_name: { type: jspsych.ParameterType.STRING, default: "" },
      total_messages: { type: jspsych.ParameterType.INT, default: 24 },
      max_chars: { type: jspsych.ParameterType.INT, default: 1000 },
      client: { type: jspsych.ParameterType.OBJECT, default: null },
      // After this long without a reply, the status line says the reply is taking a while.
      // Live replies take several seconds (about 12 s for an opener and 6 s for a reply in the first
      // synthetic test), so the "still writing" note only appears after a longer wait.
      slow_after_ms: { type: jspsych.ParameterType.INT, default: 10000 },
      // Receipt is checked again at this point if it was not confirmed at slow_after_ms.
      very_slow_after_ms: { type: jspsych.ParameterType.INT, default: 30000 },
      // A dropped connection is re-sent this many times automatically (same message, same deadline).
      auto_resends: { type: jspsych.ParameterType.INT, default: 1 },
      // After the service gives up on a reply, the participant may try this many more times.
      manual_retries: { type: jspsych.ParameterType.INT, default: 1 },
    },
    data: {
      chat_index: { type: jspsych.ParameterType.INT },
      bot_name: { type: jspsych.ParameterType.STRING },
      n_messages: { type: jspsych.ParameterType.INT },
      n_participant_messages: { type: jspsych.ParameterType.INT },
      n_bot_messages: { type: jspsych.ParameterType.INT },
      participant_chars: { type: jspsych.ParameterType.INT },
      n_failed_requests: { type: jspsych.ParameterType.INT },
      n_retries: { type: jspsych.ParameterType.INT },
      n_auto_resends: { type: jspsych.ParameterType.INT },
      // "complete", "failed", "withdrew" (the participant chose to stop, with no intervention
      // before it), "safety_stop" (the service's safety check ended this chat and the participant
      // went on), "withdrew_after_safety_stop" (they left from that notice) or "paused" (the
      // researchers paused the study).
      ended_reason: { type: jspsych.ParameterType.STRING },
      chat_started_at: { type: jspsych.ParameterType.STRING },
      chat_ended_at: { type: jspsych.ParameterType.STRING },
      duration_ms: { type: jspsych.ParameterType.INT },
    },
  };

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text; // never innerHTML: the text comes from people and a model
    return e;
  }

  class LiveChatPlugin {
    constructor(jsPsych) {
      this.jsPsych = jsPsych;
    }

    trial(display_element, trial) {
      return new Promise((resolve) => {
        const started = new Date();
        const name = trial.bot_name;
        const counts = { participant: 0, bot: 0, chars: 0, failed: 0, retries: 0, auto_resends: 0 };
        let lastSeq = 0;       // the last message shown (the hidden opener request is 0)
        let busy = false;      // a request is in flight or waiting for "Try again"
        let finished = false;
        let slowTimer = null;

        display_element.innerHTML = "";
        const box = el("div", "chat");
        box.dataset.chatIndex = String(trial.chat_index);
        const header = el("div", "chat-header", "Chat with " + name);
        const counter = el("div", "chat-counter");
        const log = el("div", "chat-log");
        log.setAttribute("aria-live", "polite");
        const status = el("div", "chat-status");
        status.setAttribute("role", "status"); // announced by screen readers
        // While a reply is being generated: a highlighted line with animated dots, outside the
        // message log (so it is never mistaken for a message or counted).
        const setStatus = (text, waiting) => {
          status.className = waiting ? "chat-status chat-waiting" : "chat-status";
          status.textContent = text;
          if (waiting) status.appendChild(el("span", "chat-dots"));
        };
        const actions = el("div", "chat-actions");
        const form = el("form", "chat-form");
        const input = el("textarea", "chat-input");
        input.rows = 2;
        input.maxLength = trial.max_chars;
        input.placeholder = "Type your message";
        input.setAttribute("aria-label", "Your message");
        const send = el("button", "jspsych-btn chat-send", "Send");
        send.type = "submit";
        form.append(input, send);
        // Always available: leave the study. Answers already saved stay saved.
        const stopRow = el("div", "chat-stop-row");
        const stop = el("button", "chat-stop", "Stop and leave the study");
        stop.type = "button";
        stopRow.appendChild(stop);
        box.append(header, counter, log, status, actions, form, stopRow);
        display_element.appendChild(box);

        // Visible messages already on screen (seq 1..total; the hidden startup instruction is 0).
        const updateCounter = () => {
          counter.textContent = Math.min(lastSeq, trial.total_messages) + " of " + trial.total_messages + " messages completed";
        };
        const setInputEnabled = (on) => {
          input.disabled = !on;
          send.disabled = !on;
          if (on) input.focus();
        };
        const addBubble = (from, text, seq) => {
          const b = el("div", "chat-msg chat-" + from, text);
          b.dataset.seq = String(seq);
          b.dataset.from = from;
          log.appendChild(b);
          log.scrollTop = log.scrollHeight;
        };

        const finish = (reason) => {
          if (finished) return;
          finished = true;
          clearTimeout(slowTimer);
          // Leaving early: tell the service, so nothing more is generated or shown for this session.
          if (reason !== "complete" && reason !== "safety_stop" && trial.client.end) trial.client.end(trial.chat_index, reason);
          const ended = new Date();
          display_element.innerHTML = "";
          resolve({
            chat_index: trial.chat_index,
            bot_name: name,
            n_messages: counts.participant + counts.bot,
            n_participant_messages: counts.participant,
            n_bot_messages: counts.bot,
            participant_chars: counts.chars,
            n_failed_requests: counts.failed,
            n_retries: counts.retries,
            n_auto_resends: counts.auto_resends,
            ended_reason: reason,
            chat_started_at: started.toISOString(),
            chat_ended_at: ended.toISOString(),
            duration_ms: ended - started,
          });
        };

        stop.onclick = () => {
          if (finished) return;
          stopRow.innerHTML = "";
          stopRow.appendChild(el("p", "chat-stop-confirm", "Leave the study now? The answers you have given so far are saved."));
          const yes = el("button", "jspsych-btn chat-stop-yes", "Yes, leave the study");
          yes.type = "button";
          yes.onclick = () => finish("withdrew");
          const no = el("button", "jspsych-btn chat-stop-no", "Keep chatting");
          no.type = "button";
          no.onclick = () => { stopRow.innerHTML = ""; stopRow.appendChild(stop); };
          stopRow.append(yes, no);
          yes.focus();
        };

        // The safety check ended this chat. Shown as a notice from the study, not from the bot.
        const safetyStop = () => {
          form.remove();
          stopRow.remove();
          actions.innerHTML = "";
          status.textContent = "";
          const note = el("div", "chat-end chat-safety-stop");
          note.appendChild(el("p", null, "This chat has been ended early by the study's automatic check. " +
            "The answers you have given so far are saved. You can continue with the study, or leave it now."));
          const next = el("button", "jspsych-btn chat-continue", "Continue");
          next.type = "button";
          next.onclick = () => finish("safety_stop");
          const leave = el("button", "jspsych-btn chat-leave", "Leave the study");
          leave.type = "button";
          leave.onclick = () => finish("withdrew_after_safety_stop"); // not the same as choosing to stop unprompted
          note.append(next, leave);
          box.appendChild(note);
          next.focus();
        };

        const endOfChat = () => {
          form.remove();
          stopRow.remove();
          actions.innerHTML = "";
          status.textContent = "";
          counter.textContent = trial.total_messages + " of " + trial.total_messages + " messages completed";
          const note = el("div", "chat-end");
          note.appendChild(el("p", null, "Your chat with " + name + " has ended."));
          const next = el("button", "jspsych-btn chat-continue", "Continue");
          next.type = "button";
          next.onclick = () => finish("complete");
          note.appendChild(next);
          box.appendChild(note);
          next.focus();
        };

        const actionButton = (label, cls, onclick) => {
          const b = el("button", "jspsych-btn " + cls, label);
          b.type = "button";
          b.onclick = onclick;
          actions.appendChild(b);
        };

        // Send one participant message (or the opener request) and show the reply.
        //   Ordinary slow replies need nothing from the participant: the service keeps one call
        //   running, within one deadline for the message (server/config.js), while the status line
        //   says honestly that it is taking a while; "Stop and leave the study" stays available.
        //   A dropped connection (no answer from the service at all) is re-sent once,
        //   automatically, with the same message number: the service joins it to the request
        //   already running and keeps that request's deadline, so it cannot cause a second call.
        //   If the service says the reply could not be made within its deadline, the participant
        //   may try once more ("Try again", a new deadline); after that, only the exit.
        // mode: "first" (sent by the participant), "auto" (the automatic re-send), "manual".
        let autoResendsHere = 0;
        let manualRetriesHere = 0;
        // The delayed-reply text is neutral, and says the message was received only when the
        // service confirms it (a read-only /status check). "Stop and leave the study" stays
        // available below the chat throughout, without being pressed on the participant here.
        let receivedConfirmed = false;
        const delayedText = (seq) => seq === 0
          ? "The first message is taking longer than usual. Please don't refresh the page."
          : receivedConfirmed
            ? "The response is taking longer than usual. Your message has been received; please don't refresh the page."
            : "The response is taking longer than usual. Please don't refresh the page.";
        let sentAt = 0;
        const request = (seq, text, mode) => {
          mode = mode || "first";
          busy = true;
          setInputEnabled(false);
          actions.innerHTML = "";
          if (mode !== "auto") {
            // The waiting clock runs from the participant's own send (or "Try again"), across any re-send.
            sentAt = Date.now();
            if (mode === "first") { autoResendsHere = 0; manualRetriesHere = 0; }
            setStatus(seq === 0 ? name + " is writing the first message" : name + " is writing a reply", true);
          }
          clearTimeout(slowTimer);
          if (mode === "first") receivedConfirmed = false;
          // At each threshold (10 s, then 30 s if receipt was not yet confirmed): ask the service
          // whether the message is saved, then show the neutral delayed-reply text.
          const tick = () => {
            const waited = Date.now() - sentAt;
            if (waited >= trial.slow_after_ms) {
              const show = () => { if (busy && !finished) setStatus(delayedText(seq), true); };
              if (seq > 0 && !receivedConfirmed && trial.client.status) {
                trial.client.status(trial.chat_index, seq).then((st) => { if (st && st.received) receivedConfirmed = true; show(); });
              } else show();
            }
            const next = [trial.slow_after_ms, trial.very_slow_after_ms].map((x) => x - waited).filter((x) => x > 0);
            if (next.length) slowTimer = setTimeout(tick, Math.min(...next) + 5);
          };
          tick();
          trial.client.turn(trial.chat_index, seq, text, mode === "first" ? undefined : mode).then((res) => {
            clearTimeout(slowTimer);
            if (finished) return;
            busy = false;
            setStatus("", false);
            if (res.stopped) return safetyStop();
            if (res.reply) {
              lastSeq = res.reply.seq;
              counts.bot += 1;
              addBubble("bot", String(res.reply.text), lastSeq);
            }
            updateCounter();
            if (res.done) endOfChat();
            else setInputEnabled(true);
          }, (err) => {
            clearTimeout(slowTimer);
            if (finished) return;
            const dropped = err && err.status === 0 && (err.code === "network" || err.code === "timeout");
            if (dropped && autoResendsHere < trial.auto_resends) {
              autoResendsHere += 1;
              counts.auto_resends += 1;
              return request(seq, text, "auto"); // silent: same message, same deadline, same status line
            }
            counts.failed += 1;
            setStatus("", false);
            if (err && err.code === "study_paused") {
              status.textContent = "The researchers have paused the study, so this chat cannot continue. The answers you have given so far are saved.";
              actionButton("Leave the study", "chat-leave", () => finish("paused"));
            } else if (err && err.retryable && manualRetriesHere < trial.manual_retries) {
              // Optional final recovery, after the service's own deadline and automatic handling.
              status.textContent = name + "'s reply could not be generated. You can try once more, or leave the study.";
              actionButton("Try again", "chat-retry", () => { counts.retries += 1; manualRetriesHere += 1; request(seq, text, "manual"); });
              actionButton("Leave the study", "chat-leave", () => finish("failed"));
            } else {
              status.textContent = "Sorry, " + name + "'s reply could not be generated, so this chat cannot continue.";
              actionButton("Leave the study", "chat-leave", () => finish("failed"));
            }
          });
        };

        form.addEventListener("submit", (ev) => {
          ev.preventDefault();
          const text = input.value.trim();
          if (busy || finished || !text) return;
          const seq = lastSeq + 1;
          lastSeq = seq;
          counts.participant += 1;
          counts.chars += text.length;
          addBubble("participant", text, seq);
          input.value = "";
          updateCounter();
          request(seq, text);
        });
        // Enter sends; Shift+Enter starts a new line.
        input.addEventListener("keydown", (ev) => {
          if (ev.key === "Enter" && !ev.shiftKey) {
            ev.preventDefault();
            form.requestSubmit();
          }
        });

        updateCounter();
        request(0, "");
      });
    }
  }
  LiveChatPlugin.info = info;
  return LiveChatPlugin;
})(jsPsychModule);
